    // FR-PROXY-022 AC-3: the platform accepts [leaf, X] only by dropping X (it has the subject and key of a given
    // certificate) and anchoring the leaf at that given certificate, which is expired; X itself is a non-CA
    // certificate the valid given CA issued, which the platform never accepts as an issuer (see the control below).
    // The only trust anchor of the accepted path is expired, so the connection must be 502 CONNECT_FAILED.
    @Test(timeout = 30000)
    public void lp_FR_PROXY_022_AC3_anExpiredGivenAnchorPassesThroughANonCaCertificateOfTheValidCa()
            throws Exception {
        TlsBackend backend = tlsBackend(presenting(crossLeaf, lpCrossByCaNotCa));
        mount(Proxy.to("https://localhost:" + backend.port()).trustCertificates(lpCrossExpiredSelfPem + caPem));

        assertConnectFailed(get(), backend);
    }
